-- Generated from reviewed JSON. Apply only after supabase_station_content_v2.sql.
begin;
do $station_release$
declare
  v_release_id uuid;
  v_release_status text;
  v_created_by uuid;
  v_is_admin boolean;
  v_item_count integer;
  v_invalid_day_count integer;
begin
  v_created_by := auth.uid();
  if v_created_by is null then
    select p.id into v_created_by from public.profiles p where p.role = 'admin' order by p.id limit 1;
  end if;
  select exists(select 1 from public.profiles p where p.id = v_created_by and p.role = 'admin') into v_is_admin;
  if v_created_by is null or not coalesce(v_is_admin, false) then
    raise exception 'station_release_import_requires_admin_profile';
  end if;
  insert into public.station_content_releases(version, grade, station_id, title, status, notes, created_by)
  values('g12-st1-2026.1', 12, 'g12_st1', 'Lớp 12 - Trạm 1: Di truyền phân tử và nhiễm sắc thể', 'draft', 'Nội dung soạn theo Chương I–II của SGK Sinh học 12 Kết nối tri thức; chờ duyệt nội dung và thử giao diện trước khi phát hành.', v_created_by)
  on conflict (version) do update set
    title = case when station_content_releases.status = 'draft' then excluded.title else station_content_releases.title end,
    notes = case when station_content_releases.status = 'draft' then excluded.notes else station_content_releases.notes end,
    updated_at = case when station_content_releases.status = 'draft' then now() else station_content_releases.updated_at end
  returning id into v_release_id;
  select status into v_release_status from public.station_content_releases where id = v_release_id for update;
  if v_release_status <> 'draft' then raise exception 'release_version_is_immutable'; end if;
  delete from public.station_content_items where release_id = v_release_id;
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 12, 'g12_st1', 1, 1, 'quiz', 'Chọn đáp án chính xác', 'Giải thích cấu trúc DNA và nguyên tắc tái bản bán bảo tồn.', '{"question":"Sau tái bản, mỗi phân tử DNA con có đặc điểm nào?","options":["Một mạch cũ và một mạch mới","Hai mạch đều cũ","Không có mạch khuôn","Chỉ gồm RNA"],"hint":"Xét nguyên tắc bán bảo tồn."}'::jsonb, '{"value":"Một mạch cũ và một mạch mới","explanation":"Mỗi DNA con có một mạch từ phân tử mẹ và một mạch mới tổng hợp."}'::jsonb, '[{"source":"SGK Sinh học 12 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 1. DNA và cơ chế tái bản DNA"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 12, 'g12_st1', 1, 2, 'match', 'Nối khái niệm với đặc điểm', 'Giải thích cấu trúc DNA và nguyên tắc tái bản bán bảo tồn.', '{"leftItems":["Mạch khuôn","DNA polymerase","Bán bảo tồn"],"rightItems":["DNA con giữ một mạch cũ","Tham gia kéo dài mạch DNA mới","Định hướng tổng hợp mạch mới"],"hint":"Phân biệt vai trò của “Mạch khuôn” và “DNA polymerase” trước khi nối. Mô tả của “Mạch khuôn” bắt đầu bằng “Đ”."}'::jsonb, '{"value":[{"left":"Mạch khuôn","right":"Định hướng tổng hợp mạch mới"},{"left":"DNA polymerase","right":"Tham gia kéo dài mạch DNA mới"},{"left":"Bán bảo tồn","right":"DNA con giữ một mạch cũ"}],"explanation":"Mạch khuôn: Định hướng tổng hợp mạch mới; DNA polymerase: Tham gia kéo dài mạch DNA mới; Bán bảo tồn: DNA con giữ một mạch cũ."}'::jsonb, '[{"source":"SGK Sinh học 12 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 1. DNA và cơ chế tái bản DNA"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 12, 'g12_st1', 1, 3, 'fill', 'Hoàn thiện kiến thức', 'Giải thích cấu trúc DNA và nguyên tắc tái bản bán bảo tồn.', '{"sentence":"DNA tái bản theo nguyên tắc bổ sung và bán [blank].","hint":"Xét ngữ cảnh của ô trống trong “DNA tái bản theo nguyên tắc bổ sung và bán [blank].”. Từ cần chọn bắt đầu bằng “b” và gồm 2 tiếng."}'::jsonb, '{"value":"bảo tồn","explanation":"Từ cần điền là “bảo tồn”."}'::jsonb, '[{"source":"SGK Sinh học 12 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 1. DNA và cơ chế tái bản DNA"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 12, 'g12_st1', 1, 4, 'category', 'Phân loại đúng nhóm', 'Giải thích cấu trúc DNA và nguyên tắc tái bản bán bảo tồn.', '{"categories":["Tham gia tái bản DNA","Không phải thành phần trực tiếp của tái bản"],"items":["Mạch DNA khuôn","Nucleotide tự do","DNA polymerase","Ribosome dịch mã"],"hint":"Phân biệt hai nhóm “Tham gia tái bản DNA” và “Không phải thành phần trực tiếp của tái bản” theo đặc điểm của từng mục. “Mạch DNA khuôn” thuộc nhóm “Tham gia tái bản DNA”."}'::jsonb, '{"value":[{"name":"Mạch DNA khuôn","catIndex":0},{"name":"Nucleotide tự do","catIndex":0},{"name":"DNA polymerase","catIndex":0},{"name":"Ribosome dịch mã","catIndex":1}],"explanation":"Mạch DNA khuôn thuộc nhóm Tham gia tái bản DNA; Nucleotide tự do thuộc nhóm Tham gia tái bản DNA; DNA polymerase thuộc nhóm Tham gia tái bản DNA; Ribosome dịch mã thuộc nhóm Không phải thành phần trực tiếp của tái bản."}'::jsonb, '[{"source":"SGK Sinh học 12 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 1. DNA và cơ chế tái bản DNA"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 12, 'g12_st1', 1, 5, 'dragdrop', 'Kéo từ hoàn thành câu', 'Giải thích cấu trúc DNA và nguyên tắc tái bản bán bảo tồn.', '{"textWithBlanks":"Base A trên mạch khuôn DNA bắt cặp với base [blank] trên mạch mới.","bankWords":["T","U","G"],"hint":"Thử từng từ trong kho vào câu “Base A trên mạch khuôn DNA bắt cặp với base [blank] trên mạch mới.” để tạo phát biểu đúng. Từ cần chọn bắt đầu bằng “T” và gồm 1 tiếng."}'::jsonb, '{"value":"T","explanation":"Từ đúng là “T”."}'::jsonb, '[{"source":"SGK Sinh học 12 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 1. DNA và cơ chế tái bản DNA"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 12, 'g12_st1', 2, 1, 'quiz', 'Chọn đáp án chính xác', 'Mô tả dòng thông tin di truyền từ gene đến protein.', '{"question":"Trong phiên mã, sản phẩm trực tiếp thường là gì?","options":["RNA","Protein hoàn chỉnh","DNA con","Lipid"],"hint":"Thông tin gene được chép sang dạng này."}'::jsonb, '{"value":"RNA","explanation":"Phiên mã tạo RNA từ mạch DNA khuôn."}'::jsonb, '[{"source":"SGK Sinh học 12 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 2. Gene, quá trình truyền đạt thông tin di truyền và hệ gene"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 12, 'g12_st1', 2, 2, 'match', 'Nối khái niệm với đặc điểm', 'Mô tả dòng thông tin di truyền từ gene đến protein.', '{"leftItems":["Phiên mã","Dịch mã","Ribosome"],"rightItems":["Nơi diễn ra dịch mã","Tổng hợp chuỗi amino acid theo mRNA","Tổng hợp RNA từ DNA"],"hint":"Phân biệt vai trò của “Phiên mã” và “Dịch mã” trước khi nối. Mô tả của “Phiên mã” bắt đầu bằng “T”."}'::jsonb, '{"value":[{"left":"Phiên mã","right":"Tổng hợp RNA từ DNA"},{"left":"Dịch mã","right":"Tổng hợp chuỗi amino acid theo mRNA"},{"left":"Ribosome","right":"Nơi diễn ra dịch mã"}],"explanation":"Phiên mã: Tổng hợp RNA từ DNA; Dịch mã: Tổng hợp chuỗi amino acid theo mRNA; Ribosome: Nơi diễn ra dịch mã."}'::jsonb, '[{"source":"SGK Sinh học 12 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 2. Gene, quá trình truyền đạt thông tin di truyền và hệ gene"}]'::jsonb);
