  values(v_release_id, 12, 'g12_st1', 2, 5, 'dragdrop', 'Kéo từ hoàn thành câu', 'Mô tả dòng thông tin di truyền từ gene đến protein.', '{"textWithBlanks":"Thông tin từ DNA qua mRNA được dùng để tổng hợp [blank].","bankWords":["protein","cellulose","nước"],"hint":"Thử từng từ trong kho vào câu “Thông tin từ DNA qua mRNA được dùng để tổng hợp [blank].” để tạo phát biểu đúng. Từ cần chọn bắt đầu bằng “p” và gồm 1 tiếng."}'::jsonb, '{"value":"protein","explanation":"Từ đúng là “protein”."}'::jsonb, '[{"source":"SGK Sinh học 12 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 2. Gene, quá trình truyền đạt thông tin di truyền và hệ gene"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
  values(v_release_id, 12, 'g12_st1', 3, 1, 'quiz', 'Chọn đáp án chính xác', 'Nêu ý nghĩa của điều hoà biểu hiện gene.', '{"question":"Vì sao các tế bào cùng cơ thể có thể thực hiện chức năng khác nhau dù mang bộ gene gần như giống nhau?","options":["Chúng biểu hiện các nhóm gene khác nhau","Mọi tế bào không có DNA","Chúng luôn có số nhiễm sắc thể khác nhau","Protein không liên quan chức năng"],"hint":"Không phải gene nào cũng hoạt động như nhau."}'::jsonb, '{"value":"Chúng biểu hiện các nhóm gene khác nhau","explanation":"Các tế bào biểu hiện các gene khác nhau để tạo protein phù hợp chức năng."}'::jsonb, '[{"source":"SGK Sinh học 12 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 3. Điều hoà biểu hiện gene"}]'::jsonb);
