  values(v_release_id, 12, 'g12_st1', 10, 5, 'dragdrop', 'Kéo từ hoàn thành câu', 'Phân biệt liên kết gene và hoán vị gene trong giảm phân.', '{"textWithBlanks":"Hoán vị gene liên quan trao đổi chéo giữa các chromatid không [blank].","bankWords":["chị em","cùng loài","cùng tế bào"],"hint":"Thử từng từ trong kho vào câu “Hoán vị gene liên quan trao đổi chéo giữa các chromatid không [blank].” để tạo phát biểu đúng. Từ cần chọn bắt đầu bằng “c” và gồm 2 tiếng."}'::jsonb, '{"value":"chị em","explanation":"Từ đúng là “chị em”."}'::jsonb, '[{"source":"SGK Sinh học 12 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Chương II. Liên kết gene và hoán vị gene"}]'::jsonb);
  select count(*) into v_item_count from public.station_content_items where release_id = v_release_id;
  if v_item_count <> 50 then
    raise exception 'station_release_import_requires_50_items';
  end if;
  select count(*) into v_invalid_day_count from (
    select day_index
    from public.station_content_items
    where release_id = v_release_id
    group by day_index
    having count(*) <> 5 or count(distinct game_type) <> 5
  ) invalid_days;
  if v_invalid_day_count <> 0 then
    raise exception 'station_release_import_requires_five_unique_games_per_day';
  end if;
